class InventoryManagement:
    def __init__(self):
        """Initialize an empty dictionary to hold inventory data."""
        self.inventory = {}

    def add_item(self, item_name, quantity):
        """Add items to the inventory. If the item already exists, update the quantity by adding to the existing amount."""
        if item_name in self.inventory:
            self.inventory[item_name] += quantity
        else:
            self.inventory[item_name] = quantity

    def remove_item(self, item_name, quantity):
        """Remove specified quantity of an item. If quantity to be removed exceeds the available quantity, 
        set the item quantity to zero and print a warning."""
        if item_name in self.inventory:
            if self.inventory[item_name] > quantity:
                self.inventory[item_name] -= quantity
            elif self.inventory[item_name] == quantity:
                del self.inventory[item_name]
            else:
                print(f"Warning: Cannot remove {quantity} of {item_name}. Only {self.inventory[item_name]} available.")
                self.inventory[item_name] = 0
        else:
            print(f"Warning: {item_name} not found in inventory.")

    def update_item(self, item_name, quantity):
        """Update the quantity of an existing item by setting its quantity to the new value provided."""
        if item_name in self.inventory:
            self.inventory[item_name] = quantity
        else:
            print(f"Warning: {item_name} not found in inventory. Did you mean to add a new item?")

    def get_inventory(self):
        """Return the current state of the inventory."""
        return self.inventory
