class Node:
    def __init__(self, value, children=None, attributes=None):
        self.value = value
        self.children = children if children is not None else []
        self.attributes = attributes if attributes is not None else {}

def prune_tree(root):
    """
    Prunes the tree in-place by removing nodes that have no children, no attributes, and a value of 0.

    :param root: The root node of the tree.
    :return: The root node of the pruned tree.
    """
    if root is None:
        return None

    root.children = [child for child in (prune_tree(child) for child in root.children) if child is not None]

    if not root.children and not root.attributes and root.value == 0:
        return None

    return root
