def parse_query_string(query_string):
    """
    Parses a query string and returns a dictionary of key-value pairs.
    If a key appears more than once, the values are stored in a list.

    :param query_string: A string in the format 'key1=value1&key2=value2&...'
    :return: A dictionary with keys mapping to their corresponding values
    """
    result = {}
    if not query_string:
        return result

    pairs = query_string.split('&')
    for pair in pairs:
        key, value = pair.split('=', 1)  # Split only at the first '='

        if key in result:
            if isinstance(result[key], list):
                result[key].append(value)
            else:
                result[key] = [result[key], value]
        else:
            result[key] = value

    return result

# Example usage
query_string = "name=John&age=30&name=Jane&address=&occupation=Developer"
print(parse_query_string(query_string))
