import heapq

def get_n_smallest(numbers, n):
    """
    Returns a list of the n smallest numbers from the input list `numbers`.
    If `numbers` contains fewer than `n` elements, returns the entire list sorted.

    :param numbers: List of integers
    :param n: Integer representing the number of smallest elements to return
    :return: List of the n smallest integers
    """
    if n <= 0:
        return []

    if not numbers or n >= len(numbers):
        return sorted(numbers)

    return heapq.nsmallest(n, numbers)
