from functools import lru_cache

@lru_cache(maxsize=None)
def factorial(n: int) -> int:
    """
    Computes the factorial of a non-negative integer n using recursion.
    Utilizes the lru_cache decorator to cache results of previous computations
    to avoid redundant calculations.

    :param n: Non-negative integer for which the factorial is to be computed.
    :return: Factorial of the integer n.
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)
